// One-click "run now": fires a Claude Code routine through its API trigger.
// URL + per-routine bearer token are generated by Alex at claude.ai/code/routines
// (there is no public API for tokens) and pasted into the Agent page.

export type Which = 'gmail' | 'agent';
export interface FireCfg { url: string; token: string; savedAt: string }

const key = (w: Which) => `fire_${w}`;

export async function getFire(db: D1Database, w: Which): Promise<FireCfg | null> {
  const r = await db.prepare('SELECT value FROM app_settings WHERE key = ?').bind(key(w)).first<{ value: string }>();
  try {
    return r ? (JSON.parse(r.value) as FireCfg) : null;
  } catch {
    return null;
  }
}

export async function saveFire(db: D1Database, w: Which, cfg: FireCfg | null) {
  if (!cfg) await db.prepare('DELETE FROM app_settings WHERE key = ?').bind(key(w)).run();
  else await db.prepare("INSERT INTO app_settings (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = datetime('now')").bind(key(w), JSON.stringify(cfg)).run();
}

export function validUrl(u: string): boolean {
  return /^https:\/\/api\.anthropic\.com\/v1\/claude_code\/routines\/[\w-]+\/fire$/.test(u);
}

export async function fire(db: D1Database, w: Which, text?: string | null): Promise<{ ok: true; sessionUrl: string | null } | { ok: false; error: string }> {
  const cfg = await getFire(db, w);
  if (!cfg) return { ok: false, error: 'not_configured' };
  try {
    const res = await fetch(cfg.url, {
      method: 'POST',
      headers: {
        authorization: `Bearer ${cfg.token}`,
        'anthropic-version': '2023-06-01',
        'anthropic-beta': 'experimental-cc-routine-2026-04-01',
        'content-type': 'application/json',
      },
      body: JSON.stringify(text ? { text } : {}),
    });
    if (!res.ok) {
      const body = await res.text().catch(() => '');
      const msg = res.status === 401 || res.status === 403 ? 'Token više ne važi. Generiši novi u Claude-u i nalepi ga ovde.' : res.status === 429 ? 'Dostignut je dnevni limit pokretanja. Pokušaj kasnije.' : `Claude je vratio grešku ${res.status}. ${body.slice(0, 160)}`;
      return { ok: false, error: msg };
    }
    const j = (await res.json().catch(() => ({}))) as { claude_code_session_url?: string };
    await db.prepare("INSERT INTO app_settings (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = datetime('now')").bind(`fired_${w}`, new Date().toISOString()).run();
    return { ok: true, sessionUrl: j.claude_code_session_url ?? null };
  } catch (e) {
    return { ok: false, error: 'Claude nije dostupan. Pokušaj ponovo za minut.' };
  }
}

/** The two buttons: plain POST forms, one click, no extra steps. */
export function RunButtons({ back, solid = true }: { back: string; solid?: boolean }) {
  return (
    <span class="run-btns">
      <form method="post" action="/agent/fire/gmail">
        <input type="hidden" name="back" value={back} />
        <button type="submit" class="btn btn-line btn-sm" data-busy="Pokrećem…">Proveri mejl</button>
      </form>
      <form method="post" action="/agent/fire/agent">
        <input type="hidden" name="back" value={back} />
        <button type="submit" class={`btn ${solid ? 'btn-solid' : 'btn-line'} btn-sm`} data-busy="Pokrećem…">Pokreni agenta</button>
      </form>
    </span>
  );
}
